function getForethoughtTranslation(key, lang) {
  if (forethoughtTranslations[lang] && forethoughtTranslations[lang][key]) {
    return forethoughtTranslations[lang][key];
  }
  if (forethoughtTranslations.en && forethoughtTranslations.en[key]) {
    return forethoughtTranslations.en[key];
  }
  return null;
}

function applyForethoughtTranslations(lang) {
  
  let count = 0;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const key = element.getAttribute('data-i18n');
    if (key && (key.startsWith('review.forethought.') || key.startsWith('review.common.'))) {
      const translation = getForethoughtTranslation(key, lang);
      if (translation) {
        element.textContent = translation;
        count++;
      }
    }
  });
  
}

document.addEventListener('languageChanged', (e) => {
  const lang = e.detail.language;
  setTimeout(() => applyForethoughtTranslations(lang), 200);
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyForethoughtTranslations(currentLang);
  });
} else {
  const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
  applyForethoughtTranslations(currentLang);
}


